<body>
  <main class="page-shell">
    <header class="masthead">
      <div>
        <p class="eyebrow">Engagement record</p>
        <h1>Chronology</h1>
      </div>
      <div class="summary" aria-label="Timeline summary">
        <div class="metric">
          <strong id="event-count">0</strong>
          <span>Engagements</span>
        </div>
        <div class="metric">
          <strong id="span-count">0d</strong>
          <span>Time span</span>
        </div>
      </div>
    </header>

    <nav class="toolbar" aria-label="Filter engagements by type">
      <span class="toolbar-label">Show</span>
      <div id="filters"></div>
    </nav>

    <ol class="timeline" id="timeline" aria-live="polite"></ol>
    <p class="empty-state" id="empty-state" hidden>No engagements match this filter.</p>
  </main>

  <script>
    const activities = [
      { activity: "Seed", timestamp: "2026-07-08T10:00:00Z", type: "initiation" },
      { activity: "Sprouting", timestamp: "2026-07-14T10:00:00Z", type: "differentiation" },
      { activity: "Flowering", timestamp: "2026-07-21T10:00:00Z", type: "maturation" }
    ];

    const sortedActivities = [...activities].sort(
      (first, second) => new Date(first.timestamp) - new Date(second.timestamp)
    );
    const timeline = document.querySelector("#timeline");
    const filters = document.querySelector("#filters");
    const emptyState = document.querySelector("#empty-state");
    const dateParts = new Intl.DateTimeFormat(undefined, {
      day: "2-digit",
      month: "short",
      year: "numeric",
      timeZone: "UTC"
    });
    const timeFormat = new Intl.DateTimeFormat(undefined, {
      hour: "numeric",
      minute: "2-digit",
      timeZone: "UTC",
      timeZoneName: "short"
    });

    function renderTimeline(selectedType = "all") {
      timeline.replaceChildren();
      const visibleActivities = sortedActivities.filter(
        (item) => selectedType === "all" || item.type === selectedType
      );

      visibleActivities.forEach((item, index) => {
        const date = new Date(item.timestamp);
        const parts = Object.fromEntries(
          dateParts.formatToParts(date).filter((part) => part.type !== "literal").map((part) => [part.type, part.value])
        );
        const event = document.createElement("li");
        event.className = "event";
        event.style.animationDelay = `${index * 80}ms`;

        const dateElement = document.createElement("time");
        dateElement.className = "date";
        dateElement.dateTime = item.timestamp;
        dateElement.innerHTML = `<span class="date-day">${parts.day}</span><span class="date-month">${parts.month} ${parts.year}</span>`;

        const markerWrap = document.createElement("div");
        markerWrap.className = "marker-wrap";
        markerWrap.setAttribute("aria-hidden", "true");
        const marker = document.createElement("span");
        marker.className = "marker";
        markerWrap.append(marker);

        const card = document.createElement("article");
        card.className = "event-card";
        const type = document.createElement("p");
        type.className = "event-type";
        type.textContent = item.type;
        const title = document.createElement("h2");
        title.className = "event-title";
        title.textContent = item.activity;
        const time = document.createElement("p");
        time.className = "event-time";
        time.textContent = timeFormat.format(date);
        const eventIndex = document.createElement("span");
        eventIndex.className = "event-index";
        eventIndex.textContent = String(sortedActivities.indexOf(item) + 1).padStart(2, "0");
        eventIndex.setAttribute("aria-hidden", "true");
        card.append(type, title, time, eventIndex);

        event.append(dateElement, markerWrap, card);
        timeline.append(event);
      });

      emptyState.hidden = visibleActivities.length > 0;
    }

    function renderFilters() {
      const types = ["all", ...new Set(sortedActivities.map((item) => item.type))];
      types.forEach((type) => {
        const button = document.createElement("button");
        button.className = "filter-button";
        button.type = "button";
        button.textContent = type === "all" ? "All" : type;
        button.dataset.type = type;
        button.setAttribute("aria-pressed", String(type === "all"));
        button.addEventListener("click", () => {
          filters.querySelectorAll("button").forEach((candidate) => {
            candidate.setAttribute("aria-pressed", String(candidate === button));
          });
          renderTimeline(type);
        });
        filters.append(button);
      });
    }

    function renderSummary() {
      document.querySelector("#event-count").textContent = sortedActivities.length;
      if (sortedActivities.length < 2) {
        document.querySelector("#span-count").textContent = "0d";
        return;
      }
      const first = new Date(sortedActivities[0].timestamp);
      const last = new Date(sortedActivities.at(-1).timestamp);
      const days = Math.round((last - first) / 86400000);
      document.querySelector("#span-count").textContent = `${days}d`;
    }

    renderFilters();
    renderSummary();
    renderTimeline();
  </script>
</body>
</html>
